catalog_script_client.script:
function onChange(control, oldValue, newValue) {
if (!newValue) return;

var ga = new GlideAjax('x_1216348_claim_0.CheckDoseClaim'); // Script Include name
ga.addParam('sysparm_name', 'checkDose'); // method name
ga.addParam('sysparm_dose', newValue); // dose selected by user

ga.getXMLAnswer(function(response) {
var result = JSON.parse(response); // convert JSON response to JS object
if (result.claimed) {
  // Show the previously claimed date
  g_form.setValue('date', result.date);

  // Display error message on the form
  g_form.showFieldMsg('dose', 'You have already claimed this dose on ' + result.date, 'error');

  // Optionally clear the selected dose so user cannot proceed
  g_form.setValue('dose', '');
} else {
  // No existing claim found — clear any previous date shown
  g_form.setValue('date', '');
}
});
}
